  <li><strong>Negative Keyword Lists:</strong> In Google Ads, we block words like <em>"free"</em>, <em>"jobs"</em>, <em>"salary"</em>, <em>"course"</em>, and <em>"pdf"</em> so you never pay for job seekers or students.</li>
  <li><strong>Immediate Follow-Up SLA:</strong> Research shows that responding to an inquiry within 5 minutes makes you <strong>21 times more likely</strong> to close the sale compared to waiting 30 minutes.</li>
